#!/usr/bin/env python3
"""批量创建modules目录下的所有缺失模块文件."""

from pathlib import Path

# 模块内容定义
MODULES = {
    "__init__.py": '''"""\nEUR实验模块包\n"""\n\nfrom .design_space import load_design_space, transform_to_numeric, generate_fallback_design_space\nfrom .oracle import create_oracle, print_oracle_spec, save_oracle_spec\nfrom .evaluation import identify_effects_from_model, evaluate_prediction_quality\nfrom .server_manager import initialize_server, verify_server_components\nfrom .sampling_loop import run_sampling_loop\nfrom .data_saver import save_sampling_data, update_summary_with_results\n\n__all__ = [\n    'load_design_space', 'transform_to_numeric', 'generate_fallback_design_space',\n    'create_oracle', 'print_oracle_spec', 'save_oracle_spec',\n    'identify_effects_from_model', 'evaluate_prediction_quality',\n    'initialize_server', 'verify_server_components',\n    'run_sampling_loop',\n    'save_sampling_data', 'update_summary_with_results'\n]\n''',

    "design_space.py": '''"""\n设计空间加载和转换模块\n"""\n\nimport pandas as pd\nimport numpy as np\nfrom typing import Tuple\nfrom pathlib import Path\n\n\ndef load_design_space(design_space_path: str) -> pd.DataFrame:\n    """加载设计空间CSV文件.\n\n    Args:\n        design_space_path: 设计空间CSV文件路径\n\n    Returns:\n        设计空间DataFrame\n    """\n    return pd.read_csv(design_space_path)\n\n\ndef transform_to_numeric(df: pd.DataFrame) -> np.ndarray:\n    """将设计空间DataFrame转换为数值数组.\n\n    Args:\n        df: 设计空间DataFrame\n\n    Returns:\n        数值化的numpy数组\n    """\n    df_numeric = df.copy()\n\n    # 处理分类变量\n    for col in df_numeric.columns:\n        if df_numeric[col].dtype == 'object':\n            # 尝试映射为数值\n            unique_vals = df_numeric[col].unique()\n            mapping = {val: i / (len(unique_vals) - 1) if len(unique_vals) > 1 else 0.0\n                      for i, val in enumerate(sorted(unique_vals))}\n            df_numeric[col] = df_numeric[col].map(mapping)\n\n    return df_numeric.astype(float).values\n\n\ndef generate_fallback_design_space(n_dims: int = 3, n_points: int = 100) -> np.ndarray:\n    """生成后备设计空间(Sobol序列或均匀随机).\n\n    Args:\n        n_dims: 维度数\n        n_points: 点数\n\n    Returns:\n        设计空间数组\n    """\n    # 简单的均匀随机采样\n    return np.random.rand(n_points, n_dims)\n''',

    "oracle.py": '''"""\nOracle模型管理模块\n"""\n\nimport numpy as np\nfrom typing import Dict, Any, Optional\nimport json\nfrom pathlib import Path\n\n\ndef create_oracle(oracle_type: str = 'simple', **kwargs) -> Any:\n    """创建Oracle模型实例.\n\n    Args:\n        oracle_type: Oracle类型\n        **kwargs: Oracle初始化参数\n\n    Returns:\n        Oracle实例\n    """\n    # 简单的Oracle实现\n    class SimpleOracle:\n        def query(self, x: np.ndarray) -> float:\n            """简单的oracle查询函数."""\n            return 1 if np.sum(x) > len(x) * 0.5 else 0\n\n    return SimpleOracle()\n\n\ndef print_oracle_spec(oracle: Any) -> None:\n    """打印Oracle规格信息.\n\n    Args:\n        oracle: Oracle实例\n    """\n    if hasattr(oracle, 'get_model_spec'):\n        spec = oracle.get_model_spec()\n        print(f"Oracle Specification:")\n        for key, value in spec.items():\n            print(f"  {key}: {value}")\n    else:\n        print(f"Oracle type: {type(oracle).__name__}")\n\n\ndef save_oracle_spec(oracle: Any, save_path: Path) -> None:\n    """保存Oracle规格到JSON文件.\n\n    Args:\n        oracle: Oracle实例\n        save_path: 保存路径\n    """\n    spec = {}\n    if hasattr(oracle, 'get_model_spec'):\n        spec = oracle.get_model_spec()\n    else:\n        spec = {'type': type(oracle).__name__}\n\n    with open(save_path, 'w') as f:\n        json.dump(spec, f, indent=2)\n''',

    "evaluation.py": '''"""\n效应识别和预测质量评估模块\n"""\n\nimport torch\nimport numpy as np\nfrom typing import Optional, Dict, Set, List, Tuple\n\n\ndef identify_effects_from_model(\n    server,\n    oracle,\n    ordinal_helper_class=None,\n    configured_pairs: Optional[List[Tuple[int, int]]] = None,\n    threshold_percentile: int = 75,\n    oracle_spec: Optional[Dict] = None\n) -> Dict:\n    """\n    从训练好的模型识别主效应和交互效应 (ANOVA风格分析)\n\n    Args:\n        server: AEPsych server实例\n        oracle: Oracle实例\n        ordinal_helper_class: Ordinal辅助类\n        configured_pairs: 预配置的交互对\n        threshold_percentile: 阈值百分位\n        oracle_spec: Oracle规格\n\n    Returns:\n        包含识别的效应的字典\n    """\n    results = {\n        'main_effects': [],\n        'interaction_effects': [],\n        'configured_pairs': configured_pairs or []\n    }\n\n    try:\n        strat = server._strats[0]\n        model = strat.model\n\n        # 提取权重(如果可用)\n        if hasattr(model, 'weights'):\n            weights = model.weights\n            # 识别主效应\n            for i, w in enumerate(weights):\n                if abs(w) > 0.1:  # 简单阈值\n                    results['main_effects'].append({'index': i, 'weight': float(w)})\n\n    except Exception as e:\n        print(f"Effect identification error: {e}")\n\n    return results\n\n\ndef evaluate_prediction_quality(\n    server,\n    test_x: torch.Tensor,\n    test_y: torch.Tensor\n) -> Dict[str, float]:\n    """\n    评估模型预测质量\n\n    Args:\n        server: AEPsych server实例\n        test_x: 测试输入\n        test_y: 测试标签\n\n    Returns:\n        评估指标字典\n    """\n    with torch.no_grad():\n        try:\n            strat = server._strats[0]\n            model = strat.model\n\n            # 预测\n            pred = model.predict(test_x)\n\n            # 计算MSE\n            mse = float(torch.mean((pred - test_y) ** 2))\n\n            return {\n                'mse': mse,\n                'n_test': len(test_y)\n            }\n        except Exception as e:\n            print(f"Evaluation error: {e}")\n            return {'error': str(e)}\n''',

    "server_manager.py": '''"""\nAEPsych Server管理模块\n"""\n\nfrom aepsych.server import AEPsychServer\nfrom aepsych.config import Config\nfrom pathlib import Path\nfrom typing import Tuple, Optional\nimport logging\n\n\ndef initialize_server(config_path: Path) -> Tuple[AEPsychServer, Config]:\n    """\n    初始化AEPsych Server\n\n    Args:\n        config_path: 配置文件路径\n\n    Returns:\n        (server, config)元组\n    """\n    logging.info(f"Loading config from {config_path}")\n\n    server = AEPsychServer()\n    config = Config.from_file(str(config_path))\n    server.configure(config)\n\n    logging.info("Server initialized successfully")\n    return server, config\n\n\ndef verify_server_components(server: AEPsychServer, config: Config) -> bool:\n    """\n    验证Server组件是否正确设置\n\n    Args:\n        server: AEPsych server实例\n        config: Config实例\n\n    Returns:\n        验证是否通过\n    """\n    try:\n        # 检查strat\n        if not hasattr(server, '_strats') or len(server._strats) == 0:\n            logging.error("Server has no strategies")\n            return False\n\n        strat = server._strats[0]\n\n        # 检查model\n        if not hasattr(strat, 'model'):\n            logging.error("Strategy has no model")\n            return False\n\n        logging.info("Server components verified")\n        return True\n\n    except Exception as e:\n        logging.error(f"Verification error: {e}")\n        return False\n''',

    "sampling_loop.py": '''"""\n采样循环执行模块\n"""\n\nimport numpy as np\nimport torch\nfrom typing import Dict, List, Any, Optional\nimport logging\n\n\ndef run_sampling_loop(\n    server,\n    oracle,\n    budget: int,\n    sobol_init: int = 0,\n    parnames: Optional[List[str]] = None\n) -> Dict[str, Any]:\n    """\n    运行采样循环\n\n    Args:\n        server: AEPsych server实例\n        oracle: Oracle实例\n        budget: 总采样预算\n        sobol_init: Sobol初始化样本数\n        parnames: 参数名称列表\n\n    Returns:\n        包含采样历史的字典\n    """\n    sampling_history = []\n    interaction_logs = []\n\n    logging.info(f"Starting sampling loop: budget={budget}, sobol_init={sobol_init}")\n\n    for trial_idx in range(budget):\n        # Ask for next configuration\n        x_config = server.ask()\n\n        # Convert to array\n        if parnames is None:\n            parnames = list(x_config.keys())\n\n        x_array = np.array([x_config[name] for name in parnames], dtype=np.float64)\n\n        # Query oracle\n        y = oracle.query(x_array)\n\n        # Tell server\n        server.tell(x_config, y)\n\n        # Log\n        sampling_history.append(x_array.tolist())\n        interaction_logs.append({\n            'trial': trial_idx,\n            'x': x_array.tolist(),\n            'y': y,\n            'x_config': x_config\n        })\n\n        if (trial_idx + 1) % 10 == 0:\n            logging.info(f"  Trial {trial_idx + 1}/{budget} completed")\n\n    return {\n        'sampling_history': sampling_history,\n        'interaction_logs': interaction_logs\n    }\n''',

    "data_saver.py": '''"""\n数据保存模块\n"""\n\nimport json\nimport numpy as np\nfrom pathlib import Path\nfrom typing import Dict, Any, List\nimport logging\n\n\ndef save_sampling_data(\n    result_dir: Path,\n    sampling_history: List,\n    interaction_logs: List[Dict]\n) -> None:\n    """\n    保存采样数据\n\n    Args:\n        result_dir: 结果目录\n        sampling_history: 采样历史\n        interaction_logs: 交互日志\n    """\n    data_dir = result_dir / 'data_files'\n    data_dir.mkdir(parents=True, exist_ok=True)\n\n    # 保存采样历史\n    history_file = data_dir / 'sampling_history.npy'\n    np.save(history_file, np.array(sampling_history))\n    logging.info(f"Saved sampling history to {history_file}")\n\n    # 保存交互日志\n    log_file = data_dir / 'interaction_log.json'\n    with open(log_file, 'w') as f:\n        json.dump(interaction_logs, f, indent=2)\n    logging.info(f"Saved interaction log to {log_file}")\n\n\ndef update_summary_with_results(\n    summary: Dict[str, Any],\n    results: Dict[str, Any]\n) -> Dict[str, Any]:\n    """\n    用结果更新摘要字典\n\n    Args:\n        summary: 现有摘要字典\n        results: 结果字典\n\n    Returns:\n        更新后的摘要\n    """\n    summary.update({\n        'n_trials': len(results.get('sampling_history', [])),\n        'sampling_completed': True\n    })\n\n    if 'effects' in results:\n        summary['identified_effects'] = results['effects']\n\n    return summary\n''',

    "param_validator.py": '''"""\nAEPsych参数验证辅助模块\n\n处理AEPsych在EUR阶段发送Condition_ID而非实际参数值的问题.\nCondition_ID是设计空间中的行索引,需要转换为实际参数值.\n"""\n\nimport pandas as pd\nimport numpy as np\nfrom typing import Dict, List, Any, Tuple\nimport logging\nimport tempfile\nfrom pathlib import Path\n\n\nclass AEPsychParamValidator:\n    """AEPsych参数验证器."""\n\n    design_space_path: str\n    validation_log_path: str\n\n    def __init__(self, design_space_path: str, validation_log_path: str = None):\n        """\n        初始化参数验证器\n\n        Args:\n            design_space_path: 设计空间CSV文件路径\n            validation_log_path: 验证日志路径(可选)\n        """\n        self.design_space = pd.read_csv(design_space_path)\n        self.valid_ranges = self._extract_valid_ranges()\n\n        if validation_log_path is None:\n            validation_log_path = Path(tempfile.gettempdir()) / 'aepsych_validation.log'\n        self.validation_log_path = validation_log_path\n\n        # 初始化日志文件\n        with open(self.validation_log_path, 'w', encoding='utf-8') as f:\n            f.write("AEPsych Parameter Validation Log\\n")\n\n        logging.info(f"[Validator] 参数验证日志: {self.validation_log_path}")\n        logging.info("=" * 80)\n\n    def _extract_valid_ranges(self) -> Dict[str, List[float]]:\n        """提取每个参数的有效值范围."""\n        valid_ranges = {}\n        for col in self.design_space.columns:\n            valid_ranges[col] = sorted(self.design_space[col].unique().tolist())\n        return valid_ranges\n\n    def validate_and_correct_params(self, x_dict: Dict[str, Any]) -> Tuple[Dict[str, Any], bool]:\n        """\n        验证并修正参数\n\n        Args:\n            x_dict: 参数字典\n\n        Returns:\n            (修正后的参数字典, 是否进行了修正)\n        """\n        corrected_dict = x_dict.copy()\n        was_corrected = False\n\n        for param, value in x_dict.items():\n            if param in self.valid_ranges:\n                valid_vals = self.valid_ranges[param]\n                if value not in valid_vals:\n                    # 找到最近的有效值\n                    closest = min(valid_vals, key=lambda v: abs(v - value))\n                    corrected_dict[param] = closest\n                    was_corrected = True\n                    self._log_validation_entry(param, value, closest)\n\n        return corrected_dict, was_corrected\n\n    def _log_validation_entry(self, param: str, original: Any, corrected: Any) -> None:\n        """记录验证条目."""\n        with open(self.validation_log_path, 'a', encoding='utf-8') as f:\n            f.write(f"[CORRECTED] {param}: {original} -> {corrected}\\n")\n\n    def log_validation_summary(self) -> None:\n        """记录验证摘要."""\n        logging.info(f"Validation log saved to: {self.validation_log_path}")\n\n\ndef integrate_param_validation(server, design_space_path: str):\n    """\n    将参数验证集成到AEPsych server中\n\n    Args:\n        server: AEPsych server实例\n        design_space_path: 设计空间路径\n\n    Returns:\n        validator实例\n    """\n    validator = AEPsychParamValidator(design_space_path)\n    # TODO: 集成到server的ask/tell流程中\n    return validator\n'''
}

def main():
    base_dir = Path("tests/is_EUR_work/00_plans/251206/scripts/modules")
    base_dir.mkdir(parents=True, exist_ok=True)

    print("Creating modules...\n")
    for filename, content in MODULES.items():
        filepath = base_dir / filename
        with open(filepath, 'w', encoding='utf-8') as f:
            f.write(content)
        print(f"[OK] Created: {filepath} ({len(content)} bytes)")

    print("\nAll modules created successfully!")

if __name__ == '__main__':
    main()
